<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { RefreshCw } from '@lucide/vue'
import DataState from '@/components/DataState.vue'
import ListPagination from '@/components/ListPagination.vue'
import StatusBadge from '@/components/StatusBadge.vue'
import { useAuthStore } from '@/stores/auth'
import { getApiErrorMessage, toApiError } from '@/services/http'
import * as logistics from '@/services/logistics'
import { displayValue } from '@/utils/display'
import { defaultLogisticsFilter, parseLogisticsQuery, toLogisticsQuery, type LogisticsFilterState } from './logisticsQuery'

const auth = useAuthStore()
const route = useRoute(); const router = useRouter()
const providers = ref<logistics.LogisticsProvider[]>([])
const channels = ref<logistics.LogisticsChannel[]>([])
const publicChannels = ref<logistics.PublicLogisticsChannel[]>([])
const publicTotal = ref(0); const publicTotalPages = ref(0)
const filter = reactive<LogisticsFilterState>({ ...defaultLogisticsFilter })
const loading = ref(false); const error = ref(''); const errorTraceId = ref<string>()
async function load() { if (loading.value) return; loading.value = true; error.value = ''; errorTraceId.value = undefined; try { if (auth.scope === 'PLATFORM') { const [p, c] = await Promise.all([logistics.listLogisticsProviders(), logistics.listLogisticsChannels()]); providers.value = p.items; channels.value = c.items } else { const data = await logistics.listAvailableLogisticsChannels({ ...filter, status: filter.status || undefined }); publicChannels.value = data.items; publicTotal.value = data.total; publicTotalPages.value = data.totalPages } } catch (cause) { const apiError = toApiError(cause); error.value = getApiErrorMessage(apiError, '物流基础资料加载失败。'); errorTraceId.value = apiError.traceId } finally { loading.value = false } }
function readQuery() { Object.assign(filter, parseLogisticsQuery(route.query)) }
async function applyQuery() { filter.page = 1; await router.push({ query: toLogisticsQuery(filter) }) }
async function resetQuery() { Object.assign(filter, defaultLogisticsFilter); await router.push({ query: {} }) }
async function changePage(page: number) { if (page >= 1 && page <= publicTotalPages.value && page !== filter.page) await router.replace({ query: toLogisticsQuery({ ...filter, page }) }) }
async function changePageSize(pageSize: number) { await router.replace({ query: toLogisticsQuery({ ...filter, page: 1, pageSize }) }) }
async function changeSort(sortField: LogisticsFilterState['sortField']) { const sortDirection = filter.sortField === sortField && filter.sortDirection === 'ASC' ? 'DESC' : 'ASC'; await router.replace({ query: toLogisticsQuery({ ...filter, sortField, sortDirection, page: 1 }) }) }
onMounted(() => { if (auth.scope !== 'PLATFORM') readQuery(); void load() })
watch(() => route.query, () => { if (auth.scope !== 'PLATFORM') { readQuery(); void load() } }, { deep: true })
</script>
<template><section><div class="page-heading"><div><span class="kicker">物流基础资料</span><h1>{{ auth.scope === 'PLATFORM' ? '物流商与渠道' : '物流渠道目录' }}</h1><p>{{ auth.scope === 'PLATFORM' ? '维护公共物流商、渠道、服务国家和已发布价格规则。' : '仅展示租户可读取的公共渠道字段；价格、成本与供应商配置不会显示。' }}</p></div><button class="btn btn--secondary" type="button" :disabled="loading" @click="load"><RefreshCw :size="16" />{{ loading ? '刷新中…' : '刷新' }}</button></div><form v-if="auth.scope !== 'PLATFORM'" class="panel filter-panel" @submit.prevent="applyQuery"><label><span>渠道编码</span><input v-model="filter.channelCode" maxlength="64" /></label><label><span>渠道名称</span><input v-model="filter.channelName" maxlength="128" /></label><label><span>服务国家</span><input v-model="filter.serviceCountry" maxlength="2" /></label><label><span>状态</span><select v-model="filter.status"><option value="">全部状态</option><option value="ACTIVE">启用</option><option value="DISABLED">停用</option></select></label><button class="btn btn--primary" type="submit">查询</button><button class="btn btn--secondary" type="button" @click="resetQuery">重置</button></form><DataState :loading="loading" :error="error" :trace-id="errorTraceId" :retry="load" :empty="auth.scope === 'PLATFORM' ? !providers.length && !channels.length : !publicChannels.length"><div v-if="auth.scope === 'PLATFORM' && providers.length" class="panel table-panel"><h2>物流商</h2><div class="data-table-wrap"><table class="data-table"><thead><tr><th>编码</th><th>名称</th><th>状态</th></tr></thead><tbody><tr v-for="item in providers" :key="item.id"><td>{{ item.providerCode }}</td><td>{{ item.providerName }}</td><td><StatusBadge :status="item.status" :label="displayValue('status', item.status)" /></td></tr></tbody></table></div></div><div class="panel table-panel"><h2>物流渠道</h2><div class="data-table-wrap"><table class="data-table"><thead><tr v-if="auth.scope === 'PLATFORM'"><th>编码</th><th>名称</th><th>运输方式</th><th>服务区域</th><th>状态</th></tr><tr v-else><th><button class="table-sort" type="button" @click="changeSort('providerName')">物流商</button></th><th><button class="table-sort" type="button" @click="changeSort('channelCode')">渠道编码</button></th><th><button class="table-sort" type="button" @click="changeSort('channelName')">渠道名称</button></th><th>运输方式</th><th>服务国家</th><th><button class="table-sort" type="button" @click="changeSort('effectiveFrom')">规则版本/生效时间</button></th><th><button class="table-sort" type="button" @click="changeSort('status')">状态</button></th></tr></thead><tbody><template v-if="auth.scope === 'PLATFORM'"><tr v-for="item in channels" :key="item.id"><td>{{ item.channelCode }}</td><td>{{ item.channelName }}</td><td>{{ displayValue('transportMode', item.transportMode) }}</td><td>{{ item.serviceArea || '当前未配置' }}</td><td><StatusBadge :status="item.status" :label="displayValue('status', item.status)" /></td></tr></template><template v-else><tr v-for="item in publicChannels" :key="item.id"><td>{{ item.providerName }}</td><td>{{ item.channelCode }}</td><td><RouterLink class="text-button" :to="{ name: 'app-logistics-detail', params: { channelId: String(item.id) }, query: toLogisticsQuery(filter) }">{{ item.channelName }}</RouterLink></td><td>{{ displayValue('transportMode', item.transportMode) }}</td><td>{{ item.serviceCountries.join('、') || '尚未配置' }}</td><td>{{ item.priceRuleVersion ?? '尚未配置' }} / {{ item.effectiveFrom ? displayValue('updatedAt', item.effectiveFrom) : '尚未配置' }}</td><td><StatusBadge :status="item.status" :label="displayValue('status', item.status)" /></td></tr></template></tbody></table></div></div></DataState><ListPagination v-if="auth.scope !== 'PLATFORM'" :page="filter.page" :page-size="filter.pageSize" :total="publicTotal" :total-pages="publicTotalPages" :loading="loading" @update:page="changePage" @update:page-size="changePageSize" /></section></template>
